long long potegamod(long long a,long long kt)
{
    long long la=1LL*a;
    long long wynik=1;
    while(kt>0)
    {
        if(kt&1)wynik=(wynik*la)%mod;
        kt/=2;
        la=(la*la)%mod;
    }
    return wynik;
}
long long p(long long a,long long b)
{
    return (a*b)%mod;
}
long long podziel(long long a,long long b)
{
    return p(a,potegamod(b,mod-2));
}
long long silnia(int a)
{
    long long wyn=costo[a/100];
    int ktora=(a/100)*100;
    if(ktora==0)ktora++;
    while(ktora<=a)
    {
        wyn=(wyn*ktora)%mod;
        ktora++;
    }
    return wyn;
}
int main()
{
    int n,m,k;
    cin>>n>>m>>k;
    long long wynik=0;
    for(int r = 1;r<n;r++)
    {
        long long wyn=p(p(p(p((n-r),m),m),podziel(silnia(n*m-2),p(silnia(k-2),silnia(n*m-k)))),r);
        wynik=(wynik+wyn)%mod;
    }
    for(int r = 1;r<m;r++)
    {
        long long wyn=p(p(p(p((m-r),n),n),podziel(silnia(n*m-2),p(silnia(k-2),silnia(n*m-k)))),r);
        wynik=(wynik+wyn)%mod;
    }
    cout<<wynik;
}
